  const list = value => Array.isArray(value)?value: value ? [value] : [];
  const records = value => list(value).filter(v=>v&&typeof v==='object'&&!Array.isArray(v));
  const lines = value => Array.isArray(value)?value.map(v=>typeof v==='string'?v:v.text||textOf(v)).join('\n'):typeof value==='string'?value:textOf(value);
  const slug = value => String(value||'project').normalize('NFKD').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').slice(0,70)||'project';
  const statusNode = verdict => el('span','status '+(verdict==='PASSED IN SCOPE'?'passed':verdict==='REJECTED'?'rejected':verdict==='INVALID'?'invalid':'unknown'),verdict||'UNKNOWN');
  const dateText = value => {if(!value)return '';const d=new Date(value);return Number.isNaN(d.valueOf())?String(value):d.toLocaleString(language==='fr'?'fr-CA':'en-CA');};
  const minor = (value,currency='CAD') => Number.isFinite(value)?new Intl.NumberFormat(language==='fr'?'fr-CA':'en-CA',{style:'currency',currency}).format(value/100):t('Unknown','Inconnu');
