    if(!bridge){status.textContent=t('Manual mode is ready. To use API or local inference, launch the optional bridge and open its localhost address. See the included connection guide.','Le mode manuel est prêt. Pour l’API ou l’inférence locale, lancez le relais facultatif et ouvrez son adresse locale. Consultez le guide inclus.');controls.classList.add('hidden');return;}
