      const card=el('article','panel omega-experiment-result'),qualification=experiment.qualification||{};
      const heading=el('div','section-heading');append(heading,el('h2','',omegaExperimentText(experiment,experiment.title)||t('Self-upgrade qualification','Qualification de l’auto-amélioration')),statusNode(omegaCode(qualification.decision||experiment.status||'NOT TESTED')));append(card,heading);
      if(qualification.scientific_verdict)append(card,el('p','omega-verdict',omegaExperimentText(experiment,qualification.scientific_verdict)));
