    $('foundry-status').textContent=!bridge?t('Launch the local connector to register source experiments.','Lancez le relais local pour enregistrer des expériences de code.'):foundryState?t('Isolated research selection: ','Sélection de recherche isolée : ')+(active||t('none','aucune')):t('Inspect source experiments to load this local registry. Construction requires a configured eligible Codex connection.','Examinez les expériences pour charger ce registre local. La construction exige une connexion Codex admissible configurée.');
    renderBridgeRefresh('foundry-refresh',foundryBusy,'Inspect source experiments','Examiner les expériences de code');$('foundry-register').disabled=!ready;selector.disabled=foundryBusy;$('foundry-objective').disabled=foundryBusy;$('foundry-model').disabled=foundryBusy;$('foundry-authorize').disabled=foundryBusy;
    $('foundry-construct').disabled=!ready||!consent||selected?.status!=='registered';$('foundry-qualify').disabled=!ready||!consent||selected?.status!=='constructed';$('foundry-activate').disabled=!ready||!consent||selected?.status!=='qualified'||selected?.qualification?.correctness!=='PASS';$('foundry-rollback').disabled=!ready||!consent||!active;
    $('foundry-export').disabled=!ready||!selected||['registered','constructing','qualifying'].includes(selected.status);$('foundry-cancel').disabled=!(foundryBusy&&['construct','qualify'].includes(foundryActionName));$('foundry-evaluate').disabled=!ready||!consent||!active;$('foundry-call').disabled=foundryBusy;
    const box=$('foundry-selected');clear(box);if(selected){const row=el('div','summary-row');append(row,el('h3','',selected.objective),statusNode(omegaLabel(selected.status).toUpperCase()));append(box,row,el('p','bounded-details',t('Editable source: ','Source modifiable : ')+omegaList(selected.editable_paths).join(', ')));if(selected.candidate_sha256)append(box,el('p','omega-cap-id',t('Candidate SHA-256: ','SHA-256 du candidat : ')+selected.candidate_sha256));if(selected.qualification)append(box,omegaDetail(t('Independent qualification and comparison','Qualification indépendante et comparaison'),selected.qualification));append(box,omegaDetail(t('Frozen protocol identity, events and costs','Identité du protocole fixe, événements et coûts'),selected));}
