    const box=$('frontier-monitor-jobs');clear(box);for(const job of jobs){const card=el('article','item-card frontier-job');const head=el('div','summary-row');append(head,el('h3','',job.title||job.url),statusNode(job.enabled?t('MONITORING','SURVEILLANCE ACTIVE'):t('PAUSED','EN PAUSE')));append(card,head,el('p','omega-cap-id',job.url),el('p','subtle',t('Last observation: ','Dernière observation : ')+(job.last_status||'NEVER_POLLED')+t(' · changes: ',' · changements : ')+(job.change_count??0)));if(job.next_poll_at&&job.enabled)append(card,el('p','bounded-details',t('Next scheduled poll: ','Prochaine consultation : ')+dateText(typeof job.next_poll_at==='number'?job.next_poll_at*1000:job.next_poll_at)));const controls=el('div','button-row');for(const [action,en,fr] of [['poll','Observe once','Observer une fois'],['start','Start monitoring','Lancer la surveillance'],['stop','Pause monitoring','Mettre en pause'],['remove','Remove monitor','Retirer la surveillance']]){const button=el('button','button '+(action==='start'?'secondary':'text-button'),t(en,fr));const canStopPending=action==='stop'&&frontierBusy&&frontierActionName==='poll'&&frontierActiveJob===job.id;button.disabled=(!canStopPending&&frontierBusy)||(['start','poll'].includes(action)&&!canFetch)||(action==='start'&&job.enabled)||(action==='stop'&&!job.enabled&&!canStopPending);button.addEventListener('click',guard(()=>monitorOperation(action,{job_id:job.id})));append(controls,button);}append(card,controls,omegaDetail(t('Source hashes, timing and observation history','Empreintes, calendrier et historique des observations'),job));append(box,card);}if(!jobs.length)omegaEmpty(box,'No monitor loaded. Saving a source does not begin polling.','Aucune surveillance chargée. Enregistrer une source ne lance pas la consultation.');
